"""JSON schemas of request models, for parameter forms generated by the renderer."""

from fastapi import APIRouter

from routes.correlation_routes import AutoCorrelationRequest, CrossCorrelationRequest

router = APIRouter()

#: Forms the renderer may request, by name. Only listed models are served.
FORMS = {
    "auto_correlation": AutoCorrelationRequest,
    "cross_correlation": CrossCorrelationRequest,
}


@router.get("/{form}")
async def get_form_schema(form: str):
    """The JSON schema of one allowlisted request model."""
    model = FORMS.get(form)
    if model is None:
        return {
            "success": False,
            "data": None,
            "message": f"No form schema named {form!r}",
            "error": None,
        }
    return {
        "success": True,
        "data": model.model_json_schema(),
        "message": f"Schema for {form}",
        "error": None,
    }
